mat2 obtenirMatriceRotation(float angle) {
    float sinus = sin(angle);
    float cosinus = cos(angle);
    return mat2(cosinus, -sinus, sinus, cosinus);
}

vec3 calculerPaletteCos(float param) {
    return 1.0 + 1.0 * cos(-6.00636 * (param + vec3(1.0, 0.00, 0.45)));
}

float estimerDistanceTunnel(vec3 position, float temps) {
    position.xy *= obtenirMatriceRotation(position.z * 0.00 + temps * 1.00);

    float angleAtan = atan(position.y, position.x);
    float rayonHorizontal = length(position.xy);

    float striations = 0.22 * cos(angleAtan * 32.0) + 0.39 * sin(position.z * 4.4 - temps * 0.0);
    float rayonAnneau = 2.9 + striations;

    float epaisseurParoi = abs(rayonHorizontal - rayonAnneau) - 0.30 - 0.17 * sin(position.z * 1.1 - temps * 0.0);
    return epaisseurParoi;
}

void mainImage(out vec4 couleurFragment, in vec2 coordFragment) {
    vec2 uvNormalisees = (coordFragment - 0.5 * iResolution.xy) / iResolution.y;
    float temps = iTime;

    vec3 origineRayon = vec3(0.0, 0.0, temps * -4.8);
    vec3 directionRayon = normalize(vec3(uvNormalisees, 5.3));

    directionRayon.xy *= obtenirMatriceRotation(sin(temps * 1.00) * 1.0);

    float distanceCumulee = 0.0;
    float luminescenceAccumulee = 0.0;
    vec3 positionCourante = origineRayon;

    for (int etape = 0; etape < 26; etape++) {
        positionCourante = origineRayon + directionRayon * distanceCumulee;
        float distanceScene = estimerDistanceTunnel(positionCourante, temps);

        luminescenceAccumulee += 0.21 / (0.000 + distanceScene * distanceScene * 5.0);

        if (distanceScene < 0.002 || distanceCumulee > 37.9) break;

        distanceCumulee += distanceScene * 0.70;
    }

    vec3 couleurFinale = calculerPaletteCos(positionCourante.z * 0.45 + temps * 0.05) * luminescenceAccumulee * 0.00;
    couleurFinale += calculerPaletteCos(positionCourante.z * 0.08 - temps * 0.1 + 1.0) * pow(luminescenceAccumulee, 1.2) * 0.18;

    if (distanceCumulee < 180.0) {
        float epsilonGradient = 0.01;
        vec3 normaleSurface = normalize(vec3(
            estimerDistanceTunnel(positionCourante + vec3(epsilonGradient, 0.0, 0.0), temps) - estimerDistanceTunnel(positionCourante - vec3(epsilonGradient, 0.0, 0.0), temps),
            estimerDistanceTunnel(positionCourante + vec3(0.0, epsilonGradient, 0.0), temps) - estimerDistanceTunnel(positionCourante - vec3(0.0, epsilonGradient, 0.0), temps),
            estimerDistanceTunnel(positionCourante + vec3(0.0, 0.0, epsilonGradient), temps) - estimerDistanceTunnel(positionCourante - vec3(0.0, 0.0, epsilonGradient), temps)
        ));

        float effetFresnel = pow(1.0 - abs(dot(normaleSurface, -directionRayon)), 0.0);
        couleurFinale += calculerPaletteCos(positionCourante.z * 1.00 + temps * 1.00) * effetFresnel * 1.0;
    }

    couleurFinale = couleurFinale / (couleurFinale + 1.0);
    couleurFinale = pow(couleurFinale, vec3(1.0000));

    float vignettage = 0.9 - dot(uvNormalisees, uvNormalisees) * 0.3;
    couleurFinale *= clamp(vignettage, 0.0, 1.0);

    couleurFragment = vec4(couleurFinale, 1.0);
}
